const a=["Mavzuni tanlang","Ma’ruzani o‘qing","Taqdimotni ko‘ring","Video rolikni tomosha qiling","Virtual muzeyda kuzating (3D va 360°)","Xarita va vaqt chizig‘ida joylashtiring","Testni topshiring","Natijani ko‘ring va portfolioga qo‘shing"],i=[{n:1,short:"Manbalar kutubxonasi",brief:"Mavzular: ma’ruza, taqdimot va video",title:"Raqamli tarixiy manbalar kutubxonasi",text:"O‘zbekiston tarixi bo‘yicha 13 ta o‘quv mavzusi — har birida ma’ruza matni, taqdimot va video rolik.",to:"/app/sources"},{n:2,short:"Dars konstruktori",brief:"Manba asosida dars loyihasini yarating",title:"Interaktiv tarix darsi konstruktori",text:"Kurs, mavzu, maqsad, manbalar, muammoli savollar, metodlar, bosqichlar va baholash mezonlarini mustaqil loyihalash.",to:"/app/lessons"},{n:3,short:"Virtual muzey va xarita",brief:"3D modellar, 360° panoramalar va interaktiv xarita",title:"Virtual tarixiy sayohat va muzey",text:"Sketchfab 3D modellari va Uzbekistan360 panoramalari asosida kuzatuv, dalil va mashg‘ulot topshiriqlari.",to:"/app/museum"},{n:4,short:"Topshiriqlar",brief:"Testlar: faylni o‘qing, javobni belgilang",title:"Topshiriqlar va baholash",text:"O‘qituvchi test faylini yuklaydi va javoblar kalitini belgilaydi; talaba faylni o‘qib, A–D javoblarni belgilaydi va natijani darhol ko‘radi.",to:"/app/assignments"},{n:5,short:"Metodika",brief:"O‘qitish metodlari va tavsiyalar",title:"Metodika",text:"Raqamli manbalar bilan ishlash metodlari va ularni darsda qo‘llash bo‘yicha tavsiyalar.",to:"/app/methodology"},{n:6,short:"Shaxsiy kabinet",brief:"Portfolio, natijalar va o‘quv yo‘li",title:"Shaxsiy kabinet va elektron portfolio",text:"Shaxsiy kabinet: test natijalari, o‘quv yo‘li va o‘z ishlaringizni (PDF, Word, taqdimot) yuklab, elektron portfolio yuriting.",to:"/app/profile"}];export{a as C,i as M};
